<?php

namespace App\Http\Middleware;

use App\Exceptions\AppException;
use App\Models\Device;
use App\Support\Time;
use Closure;
use Illuminate\Http\Request;
use Illuminate\Support\Str;
use Symfony\Component\HttpFoundation\Response;

/**
 * Identifies the till making the request from the `X-Device-Id` header (generated by the POS on first run).
 * Exposes it as `$request->attributes->get('device')`. A revoked device is refused outright.
 */
class ResolveDevice
{
    public function handle(Request $request, Closure $next): Response
    {
        $id = $request->header('X-Device-Id');
        // once signed in, the token itself says which till it belongs to — the header can't be used to borrow another till's identity
        if ($request->bearerToken()) {
            $name = (string) $request->user('sanctum')?->currentAccessToken()?->name;
            if (str_starts_with($name, 'device:')) {
                $id = substr($name, 7);
            }
        }
        if ($id && Str::isUuid($id)) {
            $device = Device::find($id);
            if ($device?->revoked) {
                throw new AppException('device_revoked', [], 403);
            }
            if ($device && (! $device->last_seen_at || Time::nowMs() - $device->last_seen_at > 60_000)) {
                $device->update(['last_seen_at' => Time::nowMs()]);
            }
            $request->attributes->set('device', $device);
        }

        return $next($request);
    }
}
